const RPC = process.env.RPC || "https://api.mainnet-beta.solana.com";
const mints = [
  "6hcFSm22yz49Q4cdVxootAU1VgtjwNFcJ7rXXcNG3NQf",
  "Bastkf9yPT4pP52iBRYkD4QuuEM1eYuwZQD8Z1ChmnyY",
  "5bjyN58zKjkN1HxJSp4uij4jRczaBzSUypemq1M4j5Co",
  "EfybJoLw7fvSNhrJKWmxAB9Mf6hPkaHVCacHsmJChspF"
];
async function rpc(method, params) {
  const r = await fetch(RPC, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params })
  });
  return r.json();
}
for (const m of mints) {
  const j = await rpc("getAccountInfo", [m, { encoding: "base64" }]);
  const v = j.result && j.result.value;
  console.log(m, v ? ("EXISTS owner=" + v.owner + " lamports=" + v.lamports) : "NULL");
}
// also check pump program id presence
const prog = await rpc("getAccountInfo", ["6EF8rrecthR5Dkzon8Nwu78hRvfCKubJ14M5uBEwF6P", { encoding: "base64" }]);
console.log("pumpProgram", prog.result && prog.result.value ? "EXISTS" : "NULL");

const RPC = process.env.RPC || "https://api.mainnet-beta.solana.com";
const envKeys = Object.keys(process.env);
console.log("ENV_KEYS:", envKeys.filter(k => /WALL|PUB|KEY|ADDR|SOL|MINT|RPC|AGENT/i.test(k)).join(","));
for (const k of envKeys) {
  if (/WALLET|PUBKEY|ADDRESS|_ADDR|OWNER/i.test(k)) console.log("ENV", k, "=", process.env[k]);
}
async function rpc(method, params) {
  const r = await fetch(RPC, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params })
  });
  return r.json();
}
// rent requirements for a pump create_v2
const sizes = [["mint", 82], ["bondingCurve", 57], ["metadata", 679], ["ata", 165]];
let total = 0;
for (const [name, size] of sizes) {
  const j = await rpc("getMinimumBalanceForRentExemption", [size]);
  const v = j.result;
  console.log("rent", name, size, v);
  if (typeof v === "number") total += v;
}
console.log("TOTAL_RENT_LAMPORTS", total, "=", (total / 1e9).toFixed(6), "SOL");
// try to find wallet balance
const cand = envKeys.filter(k => /WALLET|PUBKEY|ADDRESS|_ADDR|OWNER/i.test(k)).map(k => process.env[k]).filter(v => typeof v === "string" && v.length > 30);
for (const w of cand) {
  const j = await rpc("getBalance", [w]);
  console.log("balance", w, JSON.stringify(j.result));
}
